60	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.locality(
61	                owner.getPostcode(), owner.getCity());
62	    }
63	
64	    /**
65	     * A single Luhn check digit (0-9) computed over the digits of the owner's {@code customerCode}.
66	     * Null when the customer code is absent.
67	     */
68	    default Integer checkDigit(Owner owner) {
69	        if (owner.getCustomerCode() == null) {
70	            return null;
71	        }
72	        String code = owner.getCustomerCode();
73	        int sum = 0;
74	        boolean dbl = true;
75	        for (int i = code.length() - 1; i >= 0; i--) {
76	            char c = code.charAt(i);
77	            if (c < '0' || c > '9') {
78	                continue;
79	            }
80	            int d = c - '0';
81	            if (dbl) {
82	                d *= 2;
83	                if (d > 9) {
84	                    d -= 9;
85	                }
86	            }
87	            sum += d;
88	            dbl = !dbl;
89	        }
90	        return (10 - (sum % 10)) % 10;
91	    }
